/**
 * Catalogue access.
 *
 * data/catalog.json is generated by tools/build-catalog.mjs from the files in
 * data/maps/. The site only ever reads it, so a missing or empty catalogue is a
 * normal state (a fresh deployment), not an error.
 */

const DEFAULT_URL = 'data/catalog.json';

export async function loadCatalog(url = DEFAULT_URL) {
  let response;
  try {
    response = await fetch(url, { cache: 'no-cache' });
  } catch (error) {
    throw new Error(`Could not reach the map catalogue (${error.message}).`);
  }
  if (response.status === 404) return { generated: null, maps: [] };
  if (!response.ok) throw new Error(`Catalogue request failed with HTTP ${response.status}.`);

  const data = await response.json();
  const maps = Array.isArray(data.maps) ? data.maps : [];
  return { generated: data.generated || null, maps };
}

export function findMap(catalog, slug) {
  return catalog.maps.find((entry) => entry.slug === slug) || null;
}

/** Distinct, sorted values of a field across the catalogue — used for filters. */
export function facet(catalog, field) {
  const values = new Set();
  for (const entry of catalog.maps) {
    const value = entry[field];
    if (Array.isArray(value)) value.forEach((v) => v && values.add(v));
    else if (value) values.add(value);
  }
  return [...values].sort((a, b) => a.localeCompare(b));
}

/** Free-text + facet filter, matching the controls on the landing page. */
export function filterMaps(maps, { query = '', region = '', tag = '' } = {}) {
  const needle = query.trim().toLowerCase();
  return maps.filter((entry) => {
    if (region && entry.region !== region) return false;
    if (tag && !(entry.tags || []).includes(tag)) return false;
    if (!needle) return true;
    const haystack = [entry.title, entry.description, entry.region, ...(entry.tags || [])]
      .filter(Boolean).join(' ').toLowerCase();
    return haystack.includes(needle);
  });
}
